async (page) => {
  const { exec } = require('child_process');
  const { promisify } = require('util');
  const execAsync = promisify(exec);

  try {
    // First, make the script executable
    await execAsync('chmod +x /tmp/cron_validator.sh');

    // Run the script and capture output
    const { stdout, stderr } = await execAsync('bash /tmp/cron_validator.sh');
    return `Script output: ${stdout}\nScript errors: ${stderr}`;
  } catch (error) {
    return `Error executing script: ${error.message}`;
  }
}

async (page) => {
  const fs = require('fs');
  const { execSync } = require('child_process');

  try {
    // Make the script executable
    execSync('chmod +x /tmp/cron_validator.sh');

    // Run the script and capture output
    const output = execSync('bash /tmp/cron_validator.sh', { encoding: 'utf-8' });
    return `Script output: ${output}`;
  } catch (error) {
    return `Error executing script: ${error.message}\nStderr: ${error.stderr ? error.stderr.toString() : 'N/A'}`;
  }
}
